{"description":"Compare masks after normalizing sizes","cmd":"python3 << 'EOF'
from PIL import Image
import numpy as np
from collections import Counter
def norm_mask(mask, size=64):
    im = Image.fromarray((mask*255).astype(np.uint8)).resize((size,size), Image.LANCZOS)
    a = np.array(im)
    return (a>128).astype(np.uint8)
def iou(a,b):
    inter=np.logical_and(a==1,b==1).sum(); union=np.logical_or(a==1,b==1).sum()
    return inter/union if union else 0
def crop_norm(mask):
    ys,xs=np.where(mask==1)
    m=mask[ys.min():ys.max()+1, xs.min():xs.max()+1]
    return norm_mask(m)
templates={}
for name in ['wk','wq','wr','wb','wn','wp','bk','bq','br','bb','bn','bp']:
    im = Image.open(f'/tmp/{name}.png').convert('RGBA')
    a=np.array(im)
    mask=(a[:,:,3]>120).astype(np.uint8)
    templates[name]=crop_norm(mask)
img = Image.open('/app/chess_board.png').convert('RGB')
b = np.array(img); sq=80
def bg_color(col,row):
    pts=[(col*sq+2,row*sq+2),(col*sq+sq-3,row*sq+2),(col*sq+2,row*sq+sq-3),(col*sq+sq-3,row*sq+sq-3)]
    return Counter([tuple(b[y,x]) for (x,y) in pts]).most_common(1)[0][0]
def square_mask(col,row):
    bg=np.array(bg_color(col,row))
    patch=b[row*sq:(row+1)*sq, col*sq:(col+1)*sq].astype(int)
    diff=np.abs(patch-bg).sum(axis=2)
    return (diff>60).astype(np.uint8)
for (col,row,name) in [(0,0,'a8'),(5,0,'f8'),(2,0,'c8'),(3,0,'d8'),(5,3,'f5'),(6,3,'g5'),(2,2,'c6'),(1,1,'b7'),
                       (0,7,'a1'),(7,7,'h1'),(4,7,'e1'),(4,6,'e2'),(2,7,'c1'),(0,5,'a3'),(2,5,'c3'),(1,6,'b2')]:
    m=crop_norm(square_mask(col,row))
    best=None; bestsc=-1; scores=[]
    for tname,t in templates.items():
        sc=iou(m,t)
        scores.append((sc,tname))
        if sc>bestsc:
            bestsc=sc; best=tname
    scores.sort(reverse=True)
    print(f"{name}: best={best} ({bestsc:.2f}) top4={[(s,round(x,2)) for x,s in scores[:4]]}")
EOF"}

{"description":"Validate FEN(s) with python-chess","cmd":"python3 << 'EOF'
import chess
fen1 = "r1bq1r2/1p3pp1/p1p1p3/3n1kb1/8/P1N5/1P2QPP1/R1B1K2R w KQkq - 0 1"
for fen in [fen1, fen1.replace("KQkq","-")]:
    try:
        b = chess.Board(fen)
        print("OK:", fen)
        print(b)
        print("legal moves:", len(list(b.legal_moves)))
        # check for any issues
        for sq in chess.SQUARES:
            p=b.piece_at(sq)
            if p and p.piece_type==chess.KING:
                print("king at", chess.square_name(sq), p.color)
    except Exception as e:
        print("ERR:", fen, e)
EOF"}

{"description":"Check mating moves without castling rights too","cmd":"python3 << 'EOF'
import chess
for castling in ['KQkq','-']:
    fen = f"r1bq1r2/1p3pp1/p1p1p3/3nPkbP/8/P1N5/1P2QPP1/R1B1K2R w {castling} - 0 1"
    board = chess.Board(fen)
    mates=[]
    for mv in board.legal_moves:
        b2=board.copy(); b2.push(mv)
        if b2.is_checkmate():
            mates.append(mv.uci())
    print(castling, mates)
EOF"}
